<?php account_page_start('Support','support','HELP CENTER','CUSTOMER','SUPPORT.','Questions about an order, delivery, product or return? Send our team a ticket here.',$user); ?>
<?php if($message):?><div class="app-alert dashboard-alert success"><?=htmlspecialchars($message,ENT_QUOTES,'UTF-8')?></div><?php endif;?><?php if($error):?><div class="app-alert dashboard-alert danger"><?=htmlspecialchars($error,ENT_QUOTES,'UTF-8')?></div><?php endif;?>
<section class="dashboard-tools support-grid"><article class="app-panel dashboard-card tool-card"><div class="card-topline"><span class="card-label"><?=store_h(store_t('NEW TICKET'))?></span></div><div class="tool-heading"><div><p class="card-kicker"><?=store_h(store_t('CONTACT SUPPORT'))?></p><h2><?=store_h(store_t('How can we help?'))?><?=$priority==='priority'?' · '.store_h(store_t('Priority')):''?></h2></div></div><form method="post" enctype="multipart/form-data" class="security-form support-form"><?=csrf_field()?><label><span><?=store_h(store_t('CATEGORY'))?></span><select name="category"><option value="order"><?=store_h(store_t('Order'))?></option><option value="delivery"><?=store_h(store_t('Delivery'))?></option><option value="product"><?=store_h(store_t('Product question'))?></option><option value="return"><?=store_h(store_t('Return / refund'))?></option><option value="payment"><?=store_h(store_t('Payment'))?></option><option value="account"><?=store_h(store_t('Account'))?></option><option value="other"><?=store_h(store_t('Other'))?></option></select></label><label><span><?=store_h(store_t('SUBJECT'))?></span><input name="subject" maxlength="160" required></label><label><span><?=store_h(store_t('MESSAGE'))?></span><textarea name="message" rows="6" maxlength="8000" required></textarea></label><?php if($canDiagnostics):?><label><span><?=store_h(store_t('ATTACHMENT · OPTIONAL'))?></span><input type="file" name="diagnostics" accept=".jpg,.jpeg,.png,.webp,.pdf,.zip,.log,.txt,.json"><small><?=store_h(store_t('Image, PDF, ZIP, LOG, TXT or JSON · max 15 MB'))?></small></label><?php endif;?><button class="app-button tool-button primary" type="submit"><?=store_h(store_t('OPEN TICKET'))?> ↗</button></form></article>
<aside class="app-panel dashboard-card tool-card"><div class="card-topline"><span class="card-label"><?=store_h(store_t('YOUR TICKETS'))?></span></div><?php if(!$tickets):?><p class="tool-empty"><?=store_h(store_t('No support tickets yet.'))?></p><?php else:?><div class="support-ticket-list"><?php foreach($tickets as $t):?><a class="support-ticket-item" href="<?=htmlspecialchars(route_url('support-ticket.php').'?id='.(int)$t['id'],ENT_QUOTES,'UTF-8')?>"><span><strong>#<?=(int)$t['id']?> · <?=htmlspecialchars((string)$t['subject'],ENT_QUOTES,'UTF-8')?></strong><small><?=htmlspecialchars(store_t(ucfirst((string)$t['category'])),ENT_QUOTES,'UTF-8')?> · <?=web_local_datetime($t['updated_at']??null,store_t('Unknown'))?></small><?php if(!empty($t['latest_admin_message'])):?><small class="support-ticket-reply"><b><?=store_h(store_t('SUPPORT REPLIED'))?></b> <?=htmlspecialchars((string)$t['latest_admin_message'],ENT_QUOTES,'UTF-8')?></small><?php endif;?></span><span class="support-ticket-badges"><?php if((int)($t['unread_count']??0)>0):?><b class="app-badge support-unread-badge"><?=min(99,(int)$t['unread_count'])?> <?=store_h(store_t('NEW'))?></b><?php endif;?><b class="app-badge ticket-status ticket-<?=htmlspecialchars((string)$t['status'],ENT_QUOTES,'UTF-8')?>"><?=htmlspecialchars(store_order_status_t((string)$t['status']),ENT_QUOTES,'UTF-8')?></b></span></a><?php endforeach;?></div><?php endif;?></aside></section>
<?php account_page_end('SUPPORT CENTER'); ?>
